<script setup>import SafeImage from '../components/common/SafeImage.vue';defineProps({service:Object,booking:Object,pending:Object,done:Boolean,loading:Boolean,loadError:String,actionError:String});const emit=defineEmits(['update-booking','submit','confirm','open-admin'])</script><template><main class="page booking-page"><p v-if="loading">正在读取待确认预约</p><section v-else-if="loadError"><p>{{loadError}}</p><p>请返回入口后重新打开待确认预约。</p></section><section v-else-if="service&&!done" class="booking-card"><SafeImage :src="service.image" :alt="service.imageAlt" :label="service.title"/><h2>{{service.title}}</h2><template v-if="!pending"><label>日期<input :value="booking.date" type="date" @input="emit('update-booking',{...booking,date:$event.target.value})"/></label><label>人数<input :value="booking.people" type="number" @input="emit('update-booking',{...booking,people:Number($event.target.value)})"/></label><label>联系人<input :value="booking.contact" @input="emit('update-booking',{...booking,contact:$event.target.value})"/></label><label>电话<input :value="booking.phone" @input="emit('update-booking',{...booking,phone:$event.target.value})"/></label><button class="primary" @click="emit('submit')">提交待确认预约</button></template><template v-else><p>待确认预约摘要</p><dl><dt>日期</dt><dd>{{pending.date}}</dd><dt>人数</dt><dd>{{pending.people}}</dd><dt>联系人</dt><dd>{{pending.contact}}</dd><dt>电话</dt><dd>{{pending.phone}}</dd><dt>状态</dt><dd>{{pending.status}}</dd></dl><button class="primary" @click="emit('confirm')">确认这笔预约</button></template><p v-if="actionError">{{actionError}}</p></section><section v-else-if="done"><h2>预约已确认</h2><button @click="emit('open-admin')">去运营后台查看</button></section><p v-else>未找到可预约服务</p></main></template>
